    """
def find_dict_in_list_from_key_val(dicts: Any, key: Any, value: Any) -> object {
    for `dict in dicts {
        if (key in `dict) {
            if (`dict[key] == value) {
                return `dict;
            }
        }
    }
    return None;
}

